// Ambil pesan + nomor pengirim dari payload Meta Cloud API.
// Tahan terhadap dua bentuk payload:
//  (1) webhook generik: $json.body.entry[0].changes[0].value.messages[0]
//  (2) node resmi WhatsApp Trigger: $json.entry[0].changes[0].value.messages[0]
//      (atau langsung $json.value.messages[0] / pesan langsung {from, type, ...}).
// Pesan non-teks TIDAK lagi dibuang sebagai {skip:true} tanpa field text —
// kembalikan text:'' + nonText:true supaya node IF berikutnya tidak error.
const input = $input.first().json;
const body = input.body || input;
const value = body.entry?.[0]?.changes?.[0]?.value || body.value || body;
const msg = value.messages?.[0] || (body.from ? body : null);
if (!msg) {
  return [{ json: { from: '', text: '', messageType: 'unknown', messageId: '', nonText: true } }];
}
const type = msg.type || 'unknown';
if (type !== 'text') {
  return [{ json: { from: msg.from || '', text: '', messageType: type, messageId: msg.id || '', nonText: true } }];
}
const textBody = typeof msg.text === 'string' ? msg.text : (msg.text?.body || '');
return [{ json: { from: msg.from || '', text: textBody, messageType: 'text', messageId: msg.id || '', nonText: false } }];

// Jawaban deterministik (tanpa AI) — port ringkas src/bot.js.
// Dipakai bila ENV OPENAI_ENABLED=false: sapaan, katalog, harga/stok,
// FAQ (pencocokan kata kunci), panduan order, balasan tidak dikenal.
// SENGAJA tidak ada state machine order multi-langkah di sini: tanpa AI,
// bot memandu order lalu menawarkan eskalasi ke admin untuk konfirmasi.
// Logika deterministik LENGKAP (state machine order + rekap) ada di
// src/server.js (POST /api/simulate, GET /api/recap) — itulah fallback
// penuh bila AI Agent tidak aktif.
const STORE_NAME = (typeof $env !== 'undefined' && $env.STORE_NAME) || 'Kopi Senja';
const text = $('Parse Pesan Masuk').first().json.text || '';
const products = $('Knowledge Base: Katalog (Sheets)').all().map((i) => i.json);
const faqRows = $('Knowledge Base: FAQ (Sheets)').all().map((i) => i.json);
const raw = (text || '').trim();
function normalize(s) {
  return (s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
}
const norm = normalize(raw);
const rp = (n) => 'Rp' + Number(n || 0).toLocaleString('id-ID');
function matchProduct(t) {
  const n = normalize(t);
  return products.find((p) => {
    const words = normalize(p.name).split(' ');
    const hits = words.filter((w) => w.length > 3 && n.includes(w)).length;
    const shortHits = words.filter((w) => w.length <= 3 && new RegExp(`\\b${w}\\b`).test(n)).length;
    return hits + shortHits >= 2 || (hits >= 1 && words.length <= 2);
  });
}
function matchFaq(t) {
  const n = normalize(t);
  const words = new Set(n.split(' '));
  let best = null; let bestScore = 0;
  for (const f of faqRows) {
    const kws = Array.isArray(f.keywords) ? f.keywords : String(f.keywords || '').split(';').map((s) => s.trim()).filter(Boolean);
    let score = 0;
    for (const kw of kws) {
      const k = normalize(kw);
      if (!k) continue;
      if (n.includes(k)) score += k.split(' ').length * 2;
      else if (k.split(' ').every((w) => words.has(w))) score += k.split(' ').length;
    }
    if (score > bestScore) { bestScore = score; best = f; }
  }
  return bestScore > 0 ? best : null;
}
const GREETING = `Halo! 👋 Selamat datang di *${STORE_NAME}* — toko kopi rumahan di Pekanbaru.\n\nSaya asisten otomatisnya. Saya bisa bantu:\n• Lihat katalog — ketik *katalog*\n• Tanya harga/stok — contoh: "harga arabika gayo"\n• Order — contoh: "order kopi susu 2"\n• Tanya ongkir, jam buka, pembayaran, dll.\n\nKalau butuh manusia, ketik *admin*.\n\n_Ada yang bisa saya bantu?_`;
const UNKNOWN = `Maaf, saya belum paham pertanyaan itu. 😅\n\nSaya bisa bantu soal: katalog & harga, stok, ongkir, pembayaran, cara order, dan jam buka. Ketik *katalog* untuk lihat produk, atau ketik *admin* untuk bicara dengan manusia.`;
let reply;
if (/^(halo|hai|hi|hello|pagi|siang|sore|malam|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam|menu|bantuan|help|start|mulai)\b/.test(norm)) {
  reply = GREETING;
} else if (/\bkatalog\b|\bdaftar produk\b|\bproduk apa saja\b|\bmenu\b/.test(norm)) {
  const lines = products.map((p) => `${p.id}. ${p.name} — ${rp(p.price)} (${p.stock > 0 ? `stok ${p.stock}` : 'HABIS'})`);
  reply = `☕ *Katalog ${STORE_NAME}*\n\n${lines.join('\n')}\n\nBalas dengan nama produk untuk detail, contoh: "harga arabika gayo"\natau langsung order, contoh: "order kopi susu 2".`;
} else if (/^(order|pesan|beli|mau)\b/.test(norm)) {
  const m = norm.match(/^(order|pesan|beli|mau)\b(.*)$/);
  const rest = (m ? m[2] : '').trim();
  const qtyMatch = rest.match(/\b(\d+)\s*$/);
  const qty = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;
  const productText = qtyMatch ? rest.slice(0, qtyMatch.index).trim() : rest;
  const product = matchProduct(productText);
  if (!product) {
    reply = `Maaf, produknya belum saya kenali. 😅 Ketik *katalog* untuk melihat semua produk, lalu order dengan contoh: "order arabika gayo 2".`;
  } else if (product.stock < qty) {
    reply = `Mohon maaf, stok ${product.name} tinggal ${product.stock}, tidak cukup untuk ${qty}. Mau dikurangi jumlahnya atau pilih produk lain?`;
  } else {
    const subtotal = product.price * qty;
    const shipping = subtotal >= 100000 ? 0 : 10000;
    reply =
      `Siap! ${product.name} x${qty} — ${rp(subtotal)} (ongkir ${shipping === 0 ? 'GRATIS 🎉' : rp(shipping)}).\n\n` +
      `Mode tanpa AI: saya belum bisa mengonfirmasi order otomatis. Silakan balas dengan nama, alamat, dan pembayaran (QRIS / transfer BCA / COD), lalu ketik *admin* — admin kami akan mengonfirmasi pesanan Anda dan mengirim nomor ordernya. 🙏`;
  }
} else if (/\bharga\b|\bstok\b|\bberapa\b/.test(norm) || (matchProduct(raw) && norm.length < 60)) {
  const product = matchProduct(raw);
  if (product) {
    reply = `*${product.name}*\n${product.description || ''}\nHarga: ${rp(product.price)} • ${product.stock > 0 ? `Stok: ${product.stock}` : 'Stok: HABIS'}\n\nMau order? Ketik: order ${product.name.toLowerCase()} 1`;
  } else {
    const faq = matchFaq(raw);
    reply = faq ? faq.answer : UNKNOWN;
  }
} else {
  const faq = matchFaq(raw);
  reply = faq ? faq.answer : UNKNOWN;
}
return [{ json: { reply, orderMarker: null } }];

// Hapus baris marker ORDER_CONFIRMED dari balasan AI Agent.
// Marker (bila ada) diparse ke orderMarker; barisnya TIDAK dikirim ke pelanggan.
// Format marker persis:
//   ORDER_CONFIRMED | items | subtotal | ongkir | total | nama | alamat | pembayaran
// (angka tanpa Rp/titik; items: "Nama produk xQty; ...").
const raw = $input.first().json.output ?? $input.first().json.reply ?? $input.first().json.text ?? '';
let orderMarker = null;
const kept = [];
for (const line of String(raw).split('\n')) {
  const m = line.trim().match(/^ORDER_CONFIRMED\s*\|(.*)$/);
  if (m) {
    const parts = m[1].split('|').map((s) => s.trim());
    if (parts.length >= 7) {
      orderMarker = {
        items: parts[0],
        subtotal: Number(parts[1]) || 0,
        shipping: Number(parts[2]) || 0,
        total: Number(parts[3]) || 0,
        customerName: parts[4],
        address: parts[5],
        payment: parts[6],
      };
    }
    continue; // buang baris marker dari balasan yang terlihat pelanggan
  }
  kept.push(line);
}
return [{ json: { reply: kept.join('\n').trim(), orderMarker } }];

// Hitung nomor order berikutnya dari nomor MAKSIMUM yang sudah ada (max+1),
// BUKAN dari jumlah baris — nomor tidak boleh duplikat bila ada baris yang
// dihapus dari tab Orders (mis. baris 0001 + 0009 -> #KS-0010).
// Prefix tetap "KS" (sama seperti src/store.js nextOrderNumber()).
// Ganti placeholder {{ORDER_NUMBER}} di balasan dengan nomor baru.
// Catatan: node "Baca Orders" memakai alwaysOutputData, jadi bila tab masih
// kosong $input berisi satu item kosong — hanya baris yang punya `number`
// yang dihitung.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.number);
const max = rows.reduce((m, r) => {
  const suf = String(r.number).match(/(\d+)\s*$/);
  const n = suf ? parseInt(suf[1], 10) : NaN;
  return Number.isFinite(n) ? Math.max(m, n) : m;
}, 0);
const number = '#KS-' + String(max + 1).padStart(4, '0');
const cleaned = $('Bersihkan Balasan').first().json;
const marker = cleaned.orderMarker || {};
const date = new Date().toISOString().slice(0, 10);
const reply = String(cleaned.reply || '')
  .replace(/\{\{\s*ORDER_NUMBER\s*\}\}/g, number)
  .replace(/\[\[ORDER_NUMBER\]\]/g, number);
return [{ json: {
  reply,
  order: {
    number,
    date,
    phone: $('Parse Pesan Masuk').first().json.from,
    customerName: marker.customerName || '',
    items: marker.items || '',
    subtotal: marker.subtotal || 0,
    shipping: marker.shipping || 0,
    total: marker.total || 0,
    payment: marker.payment || '',
    status: 'BELUM BAYAR',
    address: marker.address || '',
  },
} }];

// Adapter: node Google Sheets "Catat Order ke Sheets" (append) mengembalikan
// hasil API Sheets, bukan item masukannya — field `reply` dari
// "Buat Nomor Order" hilang bila langsung disambung ke "Balas via Cloud API".
// Node ini meneruskan lagi balasan (yang sudah berisi nomor order asli)
// supaya textBody Balas tetap bisa memakai {{ $json.reply }}.
const made = $('Buat Nomor Order').first().json;
return [{ json: { reply: made.reply, orderMarker: null } }];

// Port logika dailyRecap() + unpaidFollowUp() dari src/bot.js ke Code node n8n.
// Input: baris-baris tab Orders (kolom: number, date, phone, customer_name,
// items, subtotal, shipping, total, payment, status, address).
// Keluaran: { recapText, unpaid: [{number, phone, customerName, total, followUpText}] }.
// Catatan tanggal: `date` di Sheets adalah tanggal ISO (UTC, sama seperti
// dateKey di src/store.js); cron 21.00 WIB = 14.00 UTC di hari yang sama,
// jadi filter tanggal hari ini tetap benar.
const STORE_NAME = (typeof $env !== 'undefined' && $env.STORE_NAME) || 'Kopi Senja';
const rows = $input.all().map((i) => i.json).filter((r) => r && r.number);
const today = new Date().toISOString().slice(0, 10);
const rp = (n) => 'Rp' + Number(n || 0).toLocaleString('id-ID');
const list = rows.filter((o) => String(o.date || '').slice(0, 10) === today);
// Status dinormalisasi (trim + huruf besar) sebelum dibandingkan, supaya
// 'belum bayar' (lowercase) tetap dihitung belum bayar dan 'BATAL' tidak
// ikut terhitung sudah bayar / masuk revenue.
const statusOf = (o) => String(o.status || '').trim().toUpperCase();
const unpaid = list.filter((o) => statusOf(o) === 'BELUM BAYAR');
const paid = list.filter((o) => statusOf(o) !== 'BELUM BAYAR' && statusOf(o) !== 'BATAL');
const revenue = paid.reduce((s, o) => s + Number(o.total || 0), 0);
const lines = [
  `📊 *Rekap Harian ${STORE_NAME} — ${today}*`,
  '',
  `Total order: ${list.length}`,
  `Sudah bayar: ${paid.length} (${rp(revenue)})`,
  `Belum bayar: ${unpaid.length}`,
  '',
];
for (const o of list) {
  lines.push(`• ${o.number} — ${o.customer_name || o.phone} — ${rp(o.total)} — ${o.status}`);
}
if (!list.length) lines.push('Belum ada order hari ini.');
return [{ json: {
  recapText: lines.join('\n'),
  unpaid: unpaid.map((o) => ({
    number: o.number,
    phone: o.phone,
    customerName: o.customer_name || '',
    total: Number(o.total || 0),
    followUpText:
      `Halo Kak ${o.customer_name || ''}! 👋\n\n` +
      `Kami dari *${STORE_NAME}* mengingatkan pesanan *${o.number}* ` +
      `(${rp(o.total)}) belum dibayar. ` +
      `Pesanan akan kami tahan sampai akhir hari ini. ` +
      `Bila sudah transfer, silakan kirim bukti pembayarannya ke chat ini ya. Terima kasih! ☕`,
  })),
} }];

// Adapter: node SplitInBatches hanya membagi ITEM, bukan array di dalam
// satu item — jadi daftar `unpaid` dari "Hitung Rekap Harian" harus
// diuraikan dulu menjadi satu item per order sebelum masuk Split.
// Bila tidak ada order belum bayar, kembalikan [] (follow-up tidak jalan).
const recap = $('Hitung Rekap Harian').first().json;
const unpaid = (recap && recap.unpaid) || [];
return unpaid.map((o) => ({ json: o }));
